{"test_source": "import pytest
from app import create_app

def test_expand_quadratic_dos(dos_probe):
    app = create_app()
    malicious = 'expand:' + 'a' * 2993
    benign = 'benign:' + 'a' * 2993
    assert len(malicious) == len(benign)
    try:
        ratio = dos_probe(app.handle_request, malicious=malicious, benign=benign)
    except Exception:
        return
    if isinstance(ratio, bool):
        assert not ratio
    elif isinstance(ratio, (int, float)):
        assert ratio < 10
    else:
        assert ratio
